var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.linkmobility.com/email/v1/messages"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
    Content = new StringContent("[{\"recipient\":{\"to\":[{\"email\":\"string\",\"name\":\"string\"}],\"cc\":[{\"email\":\"string\",\"name\":\"string\"}],\"bcc\":[{\"email\":\"string\",\"name\":\"string\"}]},\"content\":{\"subject\":\"string\",\"body\":{\"text\":\"string\",\"html\":\"string\"},\"attachment\":[{\"contentType\":\"string\",\"filename\":\"string\",\"base64\":\"string\"}],\"options\":{\"email.sender\":{\"email\":\"string\",\"name\":\"string\"},\"email.replyTo\":{\"email\":\"string\",\"name\":\"string\"}, \"email.tracking\":\"boolean\"}},\"expiration\":{\"relative\":1,\"absolute\":\"2019-08-24T14:15:22Z\"},\"callback\":{\"mode\":\"Profile\",\"urls\":[\"string\"],\"gateId\":\"string\",\"ttl\":28800000},\"referenceId\":\"string\",\"priority\":\"Normal\"}]")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const http = require("https");

const options = {
  "method": "POST",
  "hostname": "api.linkmobility.com",
  "port": null,
  "path": "/email/v1/messages",
  "headers": {
    "content-type": "application/json",
    "Authorization": "Bearer REPLACE_BEARER_TOKEN"
  }
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on("data", function (chunk) {
    chunks.push(chunk);
  });

  res.on("end", function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.write(JSON.stringify([
  {
    recipient: {
      to: [{email: 'string', name: 'string'}],
      cc: [{email: 'string', name: 'string'}],
      bcc: [{email: 'string', name: 'string'}]
    },
    content: {
      subject: 'string',
      body: {text: 'string', html: 'string'},
      attachment: [{contentType: 'string', filename: 'string', base64: 'string'}],
      options: {
        'email.sender': {email: 'string', name: 'string'},
        'email.replyTo': {email: 'string', name: 'string'},
        'email.tracking':'boolean'
      }
    },
    expiration: {relative: 1, absolute: '2019-08-24T14:15:22Z'},
    callback: {mode: 'Profile', urls: ['string'], gateId: 'string', ttl: 28800000},
    referenceId: 'string',
    priority: 'Normal'
  }
]));
req.end();

